#!/bin/bash -p
#SBATCH -A mt01 -p general -N1 --ntasks=1 -c 48 --mem=800G -t 04:00:00
#SBATCH --no-requeue
set -euo pipefail
umask 077
export PATH=/usr/local/bin:/usr/bin:/bin CUDA_VISIBLE_DEVICES='' PYTHONDONTWRITEBYTECODE=1
PY=$(command -v python3)
exec "$PY" -I -B - "$1" <<'P'
import base64,hashlib,json,sys,zlib
raw=zlib.decompress(base64.b64decode(''))
if hashlib.sha256(raw).hexdigest()!='77267e09c391d1fa9be7c71410219b0bd64f7616fa137ac9861c7491e2eb7935':raise ValueError('Embedded source differs')
authority=json.load(open(sys.argv[1]))
if authority['identity']!='1ec4a936d86d0f93237a704e276a8b1b54dd6a7e465990d9ba6f4089ae559feb':raise ValueError('Configuration differs')
namespace={};exec(compile(raw,'p.py','exec'),namespace)
raise SystemExit(namespace['main'](authority))
P
